package com.pousadamarealta;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.pousadamarealta.database.Database;
import com.pousadamarealta.database.MessageDao;
import com.pousadamarealta.database.ReservationDao;
import com.pousadamarealta.database.RoomDao;
import com.pousadamarealta.messaging.MessagePipeline;
import com.pousadamarealta.messaging.MessageRule;
import com.pousadamarealta.messaging.rules.ArchiveCopyRule;
import com.pousadamarealta.messaging.rules.EmailValidationRule;
import com.pousadamarealta.messaging.rules.TestModeRedirectRule;
import com.pousadamarealta.service.MessageService;
import com.pousadamarealta.service.PricingCalculator;
import com.pousadamarealta.service.ReservationService;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.io.IOException;
import java.math.BigDecimal;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

@Testcontainers
public class ReservationSystemIT {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18")
        .withDatabaseName("pousada_test")
        .withUsername("test")
        .withPassword("test");

    private static Database database;
    private static ReservationService reservationService;
    private static MessageService messageService;

    @BeforeAll
    static void setup() {
        database = new Database(
            postgres.getJdbcUrl(),
            postgres.getUsername(),
            postgres.getPassword()
        );

        RoomDao roomDao = new RoomDao(database);
        ReservationDao reservationDao = new ReservationDao(database);
        MessageDao messageDao = new MessageDao(database);

        List<MessageRule> rules = new ArrayList<>();
        rules.add(new EmailValidationRule());
        rules.add(new ArchiveCopyRule());
        MessagePipeline pipeline = new MessagePipeline(rules);

        messageService = new MessageService(messageDao, pipeline);
        PricingCalculator calculator = new PricingCalculator();
        reservationService = new ReservationService(reservationDao, roomDao, calculator, messageService);
    }

    @AfterAll
    static void teardown() {
        if (database != null) {
            database.close();
        }
    }

    @Test
    void testHighSeasonPricing() {
        var reservation = reservationService.createReservation(
            "101",
            "Test User",
            "test@example.com",
            "12345678901",
            java.time.LocalDate.of(2027, 7, 10),
            java.time.LocalDate.of(2027, 7, 12),
            2,
            com.pousadamarealta.domain.RatePlan.STANDARD
        );

        assertEquals(2, reservation.getNights());
        assertEquals(new BigDecimal("299.88"), reservation.getSubtotal().divide(new BigDecimal("2")));
        assertEquals(new BigDecimal("599.76"), reservation.getSubtotal());
        assertEquals(BigDecimal.ZERO.setScale(2), reservation.getDiscount());
        assertEquals(new BigDecimal("599.76"), reservation.getTotal());
    }

    @Test
    void testNonRefundablePlan() {
        var reservation = reservationService.createReservation(
            "201",
            "Carla Dias",
            "carla@example.com",
            "11122233344",
            java.time.LocalDate.of(2027, 3, 10),
            java.time.LocalDate.of(2027, 3, 12),
            2,
            com.pousadamarealta.domain.RatePlan.NON_REFUNDABLE
        );

        assertEquals(2, reservation.getNights());
        assertEquals(new BigDecimal("779.80"), reservation.getSubtotal());
        assertEquals(new BigDecimal("116.97"), reservation.getDiscount());
        assertEquals(new BigDecimal("662.83"), reservation.getTotal());
    }

    @Test
    void testEmailValidationAndArchiveCopy() {
        var reservation = reservationService.createReservation(
            "101",
            "Valid User",
            "valid@example.com",
            "12345678901",
            java.time.LocalDate.of(2027, 5, 10),
            java.time.LocalDate.of(2027, 5, 12),
            1,
            com.pousadamarealta.domain.RatePlan.STANDARD
        );

        int messageCountBefore = messageService.getAllMessages().size();

        reservationService.confirmReservation(reservation.getId());

        var messages = messageService.getAllMessages();
        assertEquals(messageCountBefore + 2, messages.size());

        var originalMessage = messages.get(messages.size() - 2);
        assertEquals("valid@example.com", originalMessage.getTo());
        assertEquals("SENT", originalMessage.getStatus().name());

        var copyMessage = messages.get(messages.size() - 1);
        assertEquals("arquivo@pousadamarealta.com.br", copyMessage.getTo());
        assertTrue(copyMessage.getSubject().startsWith("[Cópia] "));
        assertEquals("SENT", copyMessage.getStatus().name());
    }

    @Test
    void testInvalidEmailBlocked() {
        messageService.send("invalid.email.com", "Test", "Body");

        var messages = messageService.getAllMessages();
        var blockedMessage = messages.get(messages.size() - 1);

        assertEquals("BLOCKED", blockedMessage.getStatus().name());
        assertEquals("invalid.email.com", blockedMessage.getTo());
    }

    @Test
    void testTestModeRedirect() {
        MessageDao messageDao = new MessageDao(database);

        List<MessageRule> testRules = new ArrayList<>();
        testRules.add(new EmailValidationRule());
        testRules.add(new TestModeRedirectRule());
        MessagePipeline testPipeline = new MessagePipeline(testRules);

        MessageService testMessageService = new MessageService(messageDao, testPipeline);

        testMessageService.send("original@example.com", "Test Subject", "Test Body");

        var messages = messageService.getAllMessages();
        var redirectedMessage = messages.get(messages.size() - 1);

        assertEquals("testes@pousadamarealta.com.br", redirectedMessage.getTo());
        assertTrue(redirectedMessage.getSubject().startsWith("[TESTE] "));
        assertTrue(redirectedMessage.getBody().contains("Destinatário original: original@example.com"));
        assertEquals("SENT", redirectedMessage.getStatus().name());
    }

    @Test
    void testReservationStatusTransitions() {
        var reservation = reservationService.createReservation(
            "102",
            "Status Test",
            "status@example.com",
            "98765432109",
            java.time.LocalDate.of(2027, 6, 1),
            java.time.LocalDate.of(2027, 6, 3),
            1,
            com.pousadamarealta.domain.RatePlan.STANDARD
        );

        assertEquals("PENDING", reservation.getStatus().name());

        reservation = reservationService.confirmReservation(reservation.getId());
        assertEquals("CONFIRMED", reservation.getStatus().name());
        assertEquals(reservation.getTotal(), reservation.getAmountPaid());

        reservation = reservationService.checkIn(reservation.getId());
        assertEquals("CHECKED_IN", reservation.getStatus().name());

        reservation = reservationService.checkOut(reservation.getId());
        assertEquals("CHECKED_OUT", reservation.getStatus().name());
    }

    @Test
    void testCancellationRefund() {
        var standardReservation = reservationService.createReservation(
            "201",
            "Refund Test",
            "refund@example.com",
            "11111111111",
            java.time.LocalDate.of(2027, 8, 1),
            java.time.LocalDate.of(2027, 8, 3),
            2,
            com.pousadamarealta.domain.RatePlan.STANDARD
        );

        standardReservation = reservationService.confirmReservation(standardReservation.getId());
        BigDecimal paidAmount = standardReservation.getAmountPaid();

        standardReservation = reservationService.cancelReservation(standardReservation.getId());
        assertEquals("CANCELLED", standardReservation.getStatus().name());
        assertEquals(paidAmount, standardReservation.getRefund());

        var nonRefundableReservation = reservationService.createReservation(
            "202",
            "No Refund Test",
            "norefund@example.com",
            "22222222222",
            java.time.LocalDate.of(2027, 8, 10),
            java.time.LocalDate.of(2027, 8, 12),
            2,
            com.pousadamarealta.domain.RatePlan.NON_REFUNDABLE
        );

        nonRefundableReservation = reservationService.confirmReservation(nonRefundableReservation.getId());
        nonRefundableReservation = reservationService.cancelReservation(nonRefundableReservation.getId());

        assertEquals("CANCELLED", nonRefundableReservation.getStatus().name());
        assertEquals(BigDecimal.ZERO.setScale(2), nonRefundableReservation.getRefund());
    }
}

